# Module has functions, no class. Preserve the historical package-level alias.
ScrubberCalculator: Any = None


def __getattr__(name: str) -> Any:
    """Resolve calculator aliases lazily so submodule imports stay lightweight."""
    if name not in _LAZY_EXPORTS:
        raise AttributeError(f"module {__name__!r} has no attribute {name!r}")
    module_name, attr_name = _LAZY_EXPORTS[name]
    try:
        value = getattr(import_module(module_name, __name__), attr_name)
    except ImportError as exc:
        logger.debug("%s not available: %s", name, exc)
        value = None
    globals()[name] = value
    return value


